'use strict';

const owner = {
  name: 'Ada',
  greet(other) {
    return this.name + ' greets ' + other;
  },
  delayed() {
    // ❌ plain function loses this:
    setTimeout(function () { console.log(this?.name); }, 0);   // undefined
    // ✅ arrow captures this lexically:
    setTimeout(() => console.log(this.name), 0);              // 'Ada'
  },
};

// Implicit: the dot call
owner.greet('Bob');            // 'Ada greets Bob'

// Loss of implicit binding:
const detached = owner.greet;
detached('Bob');               // TypeError: Cannot read properties of undefined

// Explicit: call / apply / bind
owner.greet.call({ name: 'Lin' }, 'Bob');   // 'Lin greets Bob'
owner.greet.apply({ name: 'Lin' }, ['Bob']);
const boundGreet = owner.greet.bind({ name: 'Lin' });
boundGreet('Bob');             // permanently 'Lin' — bind wins forever

// new: this is the fresh instance
function User(name) { this.name = name; }
const u = new User('Grace');   // this === u inside constructor

// Default: bare call in strict mode
function loose() { return this; }
loose() === undefined;         // true in strict mode / modules

// Arrow: no own this, bind/call are no-ops
const arrow = () => this;
arrow.call({ name: 'x' });     // still the outer this

